namespace CheckoutPricing.Domain;

public static class LoyaltyDiscount
{
    private const int MaximumRatePoints = 10;

    public static int PayableCents(int subtotalCents, LoyaltyTier tier)
    {
        var rate = Math.Min(BaseRatePoints(tier) + BonusPoints(subtotalCents), MaximumRatePoints);
        var discountCents = (int)((long)subtotalCents * rate / 100);

        return subtotalCents - discountCents;
    }

    private static int BaseRatePoints(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Green => 5,
        LoyaltyTier.Gold => 7,
        LoyaltyTier.Platinum => 9,
        _ => throw new ArgumentOutOfRangeException(nameof(tier)),
    };

    private static int BonusPoints(int subtotalCents) => subtotalCents switch
    {
        >= 20_000 => 3,
        >= 5_000 => 1,
        _ => 0,
    };
}
